let terrainSelection=state.factory>=0?state.factory:2,terrainZoom=1,terrainMapMode='terrain',factoryInterior=false,comparisonSites=new Set();
const terrainPositions=[[43,38],[48,24],[39,16],[65,37]];
function siteSnapshot(i){const f=factories[i],s=snapshots[i];return {production:i===2?89.2:94.8,output:Math.round(f.output*periodDays()),quality:s.quality,delivery:s.delivery,actions:assets.filter((a,n)=>jobFor(n,i).status!=='Completed').length}}
function selectTerrainFactory(i){terrainSelection=i;state.factory=i;render()}
function terrainSpark(i){return `<svg viewBox="0 0 130 34" aria-hidden="true"><path d="M2 31Q12 21 22 24T45 19T66 16T88 14T128 3" fill="none" stroke="#b1ffe0" stroke-width="2"/><circle cx="128" cy="3" r="3" fill="#b1ffe0"/></svg>`}
function networkTiles(){const s=snapshot(),f=state.factory<0?428640:factories[state.factory].output;return [['Production attainment',state.factory===2?'89.2%':'94.8%','Target 95%'],['Output',nfmt(Math.round(f*periodDays())),'Selected period'],['First-pass quality',s.quality+'%','Target 98%'],['On-time delivery',s.delivery+'%','Target 93%']].map((r,i)=>`<button class="terrain-kpi" data-viz-point="${escapeHTML(JSON.stringify({title:r[0],label:scopeName(),value:r[1],unit:'',note:r[2]}))}" onclick="go('${i===3?'Supply Chain':i===2?'Quality':'Production Overview'}')"><small>${r[0]}</small><strong>${r[1]}</strong><span>${r[2]}</span>${terrainSpark(i)}</button>`).join('')}
function siteMiniature(){return `<svg viewBox="0 0 120 75" aria-hidden="true"><ellipse cx="60" cy="63" rx="51" ry="10" fill="#9af5bc44"/><path d="M15 33 65 13 106 29 56 49Z" fill="#e0dfd5"/><path d="M15 33V58L56 72V49Z" fill="#bfc6c2"/><path d="M56 49 106 29V54L56 72Z" fill="#879b9f"/><path d="M22 39v13l25 9V48Z" fill="#74b5c6"/><path d="M63 51 98 37V50L63 63Z" fill="#b4dddc"/><path d="M45 27 71 17 92 26 66 37Z" fill="#a1b0a9"/></svg>`}
function terrainNetwork(){const i=terrainSelection,f=factories[i],s=siteSnapshot(i);return `<div class="terrain-header"><div><h1>Egypt operations <span>/ Network overview</span></h1><small><span class="dot"></span>Illustrative locations · Demo data</small></div><div class="actions">${opButton('KPI Center',"go('Business KPIs')")}${opButton('Alarms','alarmCenter()')}</div></div><div class="terrain-kpis">${networkTiles()}</div><div class="terrain-workspace"><aside class="panel terrain-directory"><h2>Factories <small>(${factories.length})</small></h2>${factories.map((x,n)=>`<button class="terrain-site-row ${n===i?'selected':''}" onclick="selectTerrainFactory(${n})"><img src="assets/factory-campus.png" alt="Illustrative factory campus"><span><strong>${x.name}</strong><small>⌖ ${x.city}</small><small class="${n===2?'warning':'positive'}">● ${n===2?'Attention':'Operating'}</small></span></button>`).join('')}</aside><section class="terrain-stage" aria-label="Illustrative Egypt factory network"><div class="terrain-art" style="transform:scale(${terrainZoom})"><img src="assets/egypt-terrain.png" alt="Illustrative 3D relief terrain of Egypt with the Nile, delta, Mediterranean and Red Sea"><span class="terrain-sea mediterranean">Mediterranean Sea</span><span class="terrain-sea redsea">Red Sea</span><span class="terrain-egypt">E G Y P T</span>${factories.map((x,n)=>`<button class="terrain-pin ${n===i?'selected':''} ${n===2?'attention':''}" style="left:${terrainPositions[n][0]}%;top:${terrainPositions[n][1]}%" onclick="selectTerrainFactory(${n})" aria-label="Select ${x.name}">${siteMiniature()}<span><strong>${x.name}</strong><small>${n===2?'● Attention':'● Operating'}</small></span></button>`).join('')}</div><div class="terrain-notice">Illustrative terrain · Factory markers are approximate</div><div class="terrain-zoom">${opButton('−','changeTerrainZoom(-.15)')}${opButton('⌖','terrainZoom=1;render()')}${opButton('+','changeTerrainZoom(.15)')}</div></section><aside class="panel terrain-selected"><div class="selected-label">▥ &nbsp; Selected factory</div><div class="row"><h2>${f.name}</h2><span class="pill ${i===2?'amber-pill':''}">${i===2?'Attention':'Operating'}</span></div><small>⌖ ${f.city}, Egypt</small><img class="terrain-campus" src="assets/factory-campus.png" alt="Illustrative pharmaceutical factory exterior"><div class="site-readings">${[['Production',s.production],['Quality',s.quality],['Delivery',s.delivery]].map(r=>`<div><span>${r[0]}</span><div class="bar"><i style="width:${r[1]}%"></i></div><strong>${r[1]}%</strong></div>`).join('')}<div><span>Maintenance</span><div class="bar"><i style="width:${s.actions/3*100}%;background:#ffd09d"></i></div><strong class="warning">${s.actions} actions</strong></div></div>${opButton('Explore factory &nbsp; ›','exploreTerrainFactory()','terrain-explore')}</aside></div><div class="terrain-bottom"><div class="segmented">${opButton('Map',"$('#back').onclick()")}${opButton('3D terrain',"terrainMapMode='terrain';render()",'active')}${opButton('Compare sites','compareTerrainSites()')}</div><span>Select a factory to inspect its buildings and readings.</span></div>`}
function changeTerrainZoom(delta){terrainZoom=Math.max(.8,Math.min(1.6,terrainZoom+delta));render()}
function exploreTerrainFactory(){state.factory=terrainSelection;factoryInterior=true;render()}
function compareTerrainSites(){openModal('Compare factory performance',`<div class="scope-label">${$('#period').value} · Illustrative data</div><div class="table-scroll"><table><tr><th>Factory</th><th>Production</th><th>Quality</th><th>Delivery</th><th>Maintenance</th></tr>${factories.map((f,i)=>{const s=siteSnapshot(i);return `<tr><td>${f.name}</td><td>${s.production}%</td><td>${s.quality}%</td><td>${s.delivery}%</td><td>${s.actions} open actions</td></tr>`}).join('')}</table></div>`);$('#modal').classList.add('wide-modal')}
const factoryBeforeTerrain=factory;factory=function(){return factoryInterior?`<div class="terrain-return">${opButton('← Factory network',"factoryInterior=false;render()")}</div>`+factoryBeforeTerrain():terrainNetwork()};
const goBeforeTerrain=go;go=function(tab){if(tab==='Factory Overview')factoryInterior=false;goBeforeTerrain(tab)};
const renderBeforeTerrain=render;render=function(){document.body.classList.toggle('terrain-network-mode',state.tab==='Factory Overview'&&!factoryInterior);if(state.factory>=0)terrainSelection=state.factory;renderBeforeTerrain()};
render();
